export const envelope = [32, 48, 32];

export default function build(api) {
  const seatY = 6;

  // Resolve palette from world theme with robust fallbacks
  const stonePrimary = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";

  const plinth = api.theme.ground?.plinth || "minecraft:cobblestone";
  const revetment = api.theme.ground?.revetment || "minecraft:mossy_cobblestone";
  const pavement = api.theme.ground?.pavement || "minecraft:stone_bricks";

  const woodPlanks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log || "minecraft:spruce_log";
  const woodStairs = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood?.fence || "minecraft:spruce_fence";
  const woodDoor = api.theme.wood?.door || "minecraft:spruce_door";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const roofSolid = api.theme.roof?.solid || "minecraft:deepslate_tiles";
  const roofStairs = api.theme.roof?.stairs || "minecraft:deepslate_tile_stairs";
  const roofSlab = api.theme.roof?.slab || "minecraft:deepslate_tile_slab";

  // Helpers for full block strings with states
  function getStairs(base, facing, half = "bottom") {
    const name = base.split("[")[0];
    return `${name}[facing=${facing},half=${half}]`;
  }
  function getSlab(base, type = "bottom") {
    const name = base.split("[")[0];
    return `${name}[type=${type}]`;
  }
  function getLog(base, axis = "y") {
    const name = base.split("[")[0];
    return `${name}[axis=${axis}]`;
  }
  function getTrapdoor(base, facing = "north", half = "bottom", open = false) {
    const name = base.split("[")[0];
    return `${name}[facing=${facing},half=${half},open=${open}]`;
  }

  // Safe boundary-checked block placement
  function setBlock(x, y, z, block) {
    if (x < 0 || x >= 32 || y < 0 || y >= 48 || z < 0 || z >= 32) return;
    api.set(x, y, z, block);
  }

  // Weathered masonry texture generator
  function pickStone(x, y, z, isBase = false) {
    const hash = Math.abs(Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453) % 1;
    if (isBase || y <= seatY + 2) {
      if (hash < 0.35) return plinth;
      if (hash < 0.55) return revetment;
      if (hash < 0.85) return stonePrimary;
      return stoneAccent;
    }
    if (hash < 0.65) return stonePrimary;
    if (hash < 0.88) return stoneAccent;
    return plinth;
  }

  // 2D Footprint definitions
  function inMainKeep(x, z) {
    return x >= 8 && x <= 23 && z >= 8 && z <= 23;
  }

  function inTurret(x, z, cx, cz) {
    const dx = Math.abs(x - cx);
    const dz = Math.abs(z - cz);
    return dx <= 2 && dz <= 2 && !(dx === 2 && dz === 2);
  }

  function inAnyTurret(x, z) {
    return (
      inTurret(x, z, 7, 7) ||
      inTurret(x, z, 24, 7) ||
      inTurret(x, z, 7, 24) ||
      inTurret(x, z, 24, 24)
    );
  }

  function inForebuilding(x, z) {
    return x >= 13 && x <= 18 && z >= 4 && z <= 7;
  }

  function inEntranceStairs(x, z) {
    return x >= 13 && x <= 18 && z >= 1 && z <= 3;
  }

  function inButtress(x, z) {
    if (x >= 14 && x <= 17 && z >= 24 && z <= 25) return true; // South chimney
    if (x >= 24 && x <= 25 && z >= 14 && z <= 17) return true; // East pilaster
    if (x >= 6 && x <= 7 && z >= 14 && z <= 17) return true;   // West pilaster
    return false;
  }

  function isBaseFootprint(x, z) {
    return inMainKeep(x, z) || inAnyTurret(x, z) || inForebuilding(x, z) || inButtress(x, z);
  }

  // Precompute distance field from structure footprint for battered base (talus)
  const distToBase = Array.from({ length: 32 }, () => new Int32Array(32).fill(999));
  for (let x = 0; x < 32; x++) {
    for (let z = 0; z < 32; z++) {
      if (isBaseFootprint(x, z)) distToBase[x][z] = 0;
    }
  }
  for (let x = 0; x < 32; x++) {
    for (let z = 0; z < 32; z++) {
      if (distToBase[x][z] === 0) continue;
      let minD = 999;
      for (let bx = 0; bx < 32; bx++) {
        for (let bz = 0; bz < 32; bz++) {
          if (distToBase[bx][bz] === 0) {
            const d = Math.max(Math.abs(x - bx), Math.abs(z - bz));
            if (d < minD) minD = d;
          }
        }
      }
      distToBase[x][z] = minD;
    }
  }

  function getTalusFacing(x, z) {
    let minD = 999;
    let bestDx = 0;
    let bestDz = 0;
    for (let bx = 0; bx < 32; bx++) {
      for (let bz = 0; bz < 32; bz++) {
        if (distToBase[bx][bz] === 0) {
          const d = Math.max(Math.abs(x - bx), Math.abs(z - bz));
          if (d < minD) {
            minD = d;
            bestDx = bx - x;
            bestDz = bz - z;
          }
        }
      }
    }
    if (Math.abs(bestDx) >= Math.abs(bestDz)) {
      return bestDx > 0 ? "west" : "east";
    } else {
      return bestDz > 0 ? "north" : "south";
    }
  }

  // 1. TERRAIN CONFORMING & SUBSTRUCTURE FOUNDATION (Rule 6)
  for (let x = 0; x < 32; x++) {
    for (let z = 0; z < 32; z++) {
      if (distToBase[x][z] <= 2 || inEntranceStairs(x, z)) {
        const gh = Math.round(api.heightAt(x, z));
        const groundY = Math.max(0, Math.min(seatY + gh, seatY + 4));
        if (groundY < seatY) {
          for (let y = groundY; y < seatY; y++) {
            setBlock(x, y, z, pickStone(x, y, z, true));
          }
        } else if (groundY > seatY) {
          for (let y = seatY; y <= groundY; y++) {
            setBlock(x, y, z, pickStone(x, y, z, true));
          }
        }
      }
    }
  }

  // Monumental entrance stairs conforming to ground
  for (let x = 13; x <= 18; x++) {
    for (let z = 1; z <= 3; z++) {
      const gh = Math.round(api.heightAt(x, z));
      const stepTargetY = seatY + (z - 2);
      const startY = Math.max(0, seatY + gh);
      for (let y = startY; y < stepTargetY; y++) {
        setBlock(x, y, z, pickStone(x, y, z, true));
      }
      if (stepTargetY >= 0 && stepTargetY < 48) {
        if (x === 13 || x === 18) {
          setBlock(x, stepTargetY, z, stonePrimary);
          setBlock(x, stepTargetY + 1, z, stoneWall);
        } else {
          setBlock(x, stepTargetY, z, getStairs(stoneStairs, "north"));
        }
      }
    }
  }

  // 2. BATTERED TALUS BASE & PLINTH COURSES (relY = 0 to 2)
  for (let x = 0; x < 32; x++) {
    for (let z = 0; z < 32; z++) {
      const d = distToBase[x][z];
      if (d === 2) {
        setBlock(x, seatY, z, getStairs(stoneStairs, getTalusFacing(x, z)));
      } else if (d === 1) {
        setBlock(x, seatY, z, pickStone(x, seatY, z, true));
        setBlock(x, seatY + 1, z, getStairs(stoneStairs, getTalusFacing(x, z)));
      } else if (d === 0) {
        setBlock(x, seatY, z, pickStone(x, seatY, z, true));
      }
    }
  }

  // 3. LEVEL 0: UNDERCROFT & GREAT VAULT (y = seatY to seatY + 6)
  // Paved floor
  for (let x = 8; x <= 23; x++) {
    for (let z = 8; z <= 23; z++) {
      const isCheck = (x + z) % 2 === 0;
      setBlock(x, seatY, z, isCheck ? pavement : stonePrimary);
    }
  }

  // Undercroft solid masonry walls
  for (let y = seatY + 1; y <= seatY + 6; y++) {
    for (let x = 8; x <= 23; x++) {
      for (let z = 8; z <= 23; z++) {
        const isOuterWall = x === 8 || x === 9 || x === 22 || x === 23 || z === 8 || z === 9 || z === 22 || z === 23;
        if (isOuterWall) {
          setBlock(x, y, z, pickStone(x, y, z));
        }
      }
    }
  }

  // Undercroft central vaulting pillars & springers
  const vaultPillars = [[12, 12], [19, 12], [12, 19], [19, 19]];
  for (const [px, pz] of vaultPillars) {
    for (let y = seatY + 1; y <= seatY + 4; y++) {
      setBlock(px, y, pz, stonePrimary);
    }
    // Capital corbels / vault springers at y = seatY + 5
    setBlock(px, seatY + 5, pz, stonePrimary);
    setBlock(px + 1, seatY + 5, pz, getStairs(stoneStairs, "east", "top"));
    setBlock(px - 1, seatY + 5, pz, getStairs(stoneStairs, "west", "top"));
    setBlock(px, seatY + 5, pz + 1, getStairs(stoneStairs, "south", "top"));
    setBlock(px, seatY + 5, pz - 1, getStairs(stoneStairs, "north", "top"));
  }

  // Vault ceiling ribs at y = seatY + 6
  for (let x = 10; x <= 21; x++) {
    setBlock(x, seatY + 6, 12, getSlab(stoneSlab, "top"));
    setBlock(x, seatY + 6, 19, getSlab(stoneSlab, "top"));
  }
  for (let z = 10; z <= 21; z++) {
    setBlock(12, seatY + 6, z, getSlab(stoneSlab, "top"));
    setBlock(19, seatY + 6, z, getSlab(stoneSlab, "top"));
  }

  // Arrow slits on undercroft exterior
  setBlock(16, seatY + 3, 23, stoneWall);
  setBlock(8, seatY + 3, 16, stoneWall);
  setBlock(23, seatY + 3, 16, stoneWall);

  // Forebuilding / North Gatehouse
  for (let y = seatY + 1; y <= seatY + 6; y++) {
    for (let x = 13; x <= 18; x++) {
      for (let z = 4; z <= 7; z++) {
        const isForeWall = x === 13 || x === 18 || z === 4;
        if (isForeWall) {
          setBlock(x, y, z, pickStone(x, y, z));
        }
      }
    }
  }
  // Gate archway opening at z = 4..7, x = 15..16
  for (let y = seatY + 1; y <= seatY + 4; y++) {
    setBlock(15, y, 4, "minecraft:air");
    setBlock(16, y, 4, "minecraft:air");
    setBlock(15, y, 7, "minecraft:air");
    setBlock(16, y, 7, "minecraft:air");
  }
  setBlock(15, seatY + 4, 4, getStairs(stoneStairs, "west", "top"));
  setBlock(16, seatY + 4, 4, getStairs(stoneStairs, "east", "top"));
  setBlock(15, seatY + 1, 7, woodDoor);
  setBlock(16, seatY + 1, 7, woodDoor);

  // Outer gate lanterns
  setBlock(13, seatY + 3, 3, "minecraft:wall_torch[facing=north]");
  setBlock(18, seatY + 3, 3, "minecraft:wall_torch[facing=north]");

  // 4. LEVEL 1: GREAT BARONIAL HALL (y = seatY + 7 to seatY + 15)
  // Timber floor of Great Hall
  for (let x = 8; x <= 23; x++) {
    for (let z = 8; z <= 23; z++) {
      const isBorder = x === 8 || x === 23 || z === 8 || z === 23;
      setBlock(x, seatY + 7, z, isBorder ? stonePrimary : woodPlanks);
    }
  }

  // Great Hall outer walls
  for (let y = seatY + 8; y <= seatY + 15; y++) {
    for (let x = 8; x <= 23; x++) {
      for (let z = 8; z <= 23; z++) {
        const isWall = x === 8 || x === 23 || z === 8 || z === 23;
        if (isWall) {
          setBlock(x, y, z, pickStone(x, y, z));
        }
      }
    }
  }

  // Grand gothic windows on West and East walls
  const windowZ = [13, 14, 17, 18];
  for (const wz of windowZ) {
    // West windows
    setBlock(8, seatY + 9, wz, getStairs(stoneStairs, "east"));
    setBlock(8, seatY + 10, wz, woodFence);
    setBlock(8, seatY + 11, wz, woodFence);
    setBlock(8, seatY + 12, wz, getStairs(stoneStairs, wz % 2 === 1 ? "north" : "south", "top"));

    // East windows
    setBlock(23, seatY + 9, wz, getStairs(stoneStairs, "west"));
    setBlock(23, seatY + 10, wz, woodFence);
    setBlock(23, seatY + 11, wz, woodFence);
    setBlock(23, seatY + 12, wz, getStairs(stoneStairs, wz % 2 === 1 ? "north" : "south", "top"));
  }

  // North lookout window
  setBlock(15, seatY + 9, 8, getStairs(stoneStairs, "south"));
  setBlock(16, seatY + 9, 8, getStairs(stoneStairs, "south"));
  setBlock(15, seatY + 10, 8, woodFence);
  setBlock(16, seatY + 10, 8, woodFence);
  setBlock(15, seatY + 11, 8, getStairs(stoneStairs, "west", "top"));
  setBlock(16, seatY + 11, 8, getStairs(stoneStairs, "east", "top"));

  // South Great Fireplace & Chimney
  for (let y = seatY + 8; y <= seatY + 15; y++) {
    for (let x = 14; x <= 17; x++) {
      setBlock(x, y, 24, stonePrimary);
      setBlock(x, y, 25, stonePrimary);
    }
  }
  // Fireplace opening inside hall
  for (let y = seatY + 8; y <= seatY + 10; y++) {
    setBlock(15, y, 23, "minecraft:air");
    setBlock(16, y, 23, "minecraft:air");
  }
  setBlock(14, seatY + 11, 23, getStairs(stoneStairs, "east", "top"));
  setBlock(17, seatY + 11, 23, getStairs(stoneStairs, "west", "top"));
  setBlock(15, seatY + 11, 23, getSlab(stoneSlab, "top"));
  setBlock(16, seatY + 11, 23, getSlab(stoneSlab, "top"));

  // Minstrel Gallery balcony at North wall (y = seatY + 11)
  for (let x = 10; x <= 21; x++) {
    setBlock(x, seatY + 11, 9, woodPlanks);
    setBlock(x, seatY + 11, 10, woodSlab);
    setBlock(x, seatY + 12, 10, woodFence);
  }

  // Timber roof trusses spanning East-West at y = seatY + 15
  const trussZ = [11, 15, 19];
  for (const tz of trussZ) {
    for (let x = 9; x <= 22; x++) {
      setBlock(x, seatY + 15, tz, getLog(woodLog, "x"));
    }
    setBlock(9, seatY + 14, tz, getStairs(woodStairs, "west", "top"));
    setBlock(22, seatY + 14, tz, getStairs(woodStairs, "east", "top"));
    // Hanging lantern from central truss
    if (tz === 15) {
      setBlock(15, seatY + 14, 15, "minecraft:chain");
      setBlock(16, seatY + 14, 16, "minecraft:chain");
    }
  }

  // 5. LEVEL 2: LORD'S SOLAR / HIGH QUARTERS (y = seatY + 16 to seatY + 23)
  // Wood floor
  for (let x = 8; x <= 23; x++) {
    for (let z = 8; z <= 23; z++) {
      const isBorder = x === 8 || x === 23 || z === 8 || z === 23;
      setBlock(x, seatY + 16, z, isBorder ? stonePrimary : woodPlanks);
    }
  }

  // High chamber walls
  for (let y = seatY + 17; y <= seatY + 23; y++) {
    for (let x = 8; x <= 23; x++) {
      for (let z = 8; z <= 23; z++) {
        const isWall = x === 8 || x === 23 || z === 8 || z === 23;
        if (isWall) {
          setBlock(x, y, z, pickStone(x, y, z));
        }
      }
    }
  }

  // Solar windows with decorative shutter corbels
  const solarWindows = [[8, 14, "east"], [8, 17, "east"], [23, 14, "west"], [23, 17, "west"]];
  for (const [wx, wz, facing] of solarWindows) {
    setBlock(wx, seatY + 18, wz, getStairs(stoneStairs, facing));
    setBlock(wx, seatY + 19, wz, woodFence);
    setBlock(wx, seatY + 20, wz, getStairs(stoneStairs, facing, "top"));
  }

  // Chimney breast continuing upward on South face
  for (let y = seatY + 16; y <= seatY + 28; y++) {
    for (let x = 15; x <= 16; x++) {
      setBlock(x, y, 24, stonePrimary);
    }
  }
  setBlock(15, seatY + 29, 24, stoneWall);
  setBlock(16, seatY + 29, 24, stoneWall);
  setBlock(15, seatY + 30, 24, getSlab(stoneSlab, "bottom"));
  setBlock(16, seatY + 30, 24, getSlab(stoneSlab, "bottom"));

  // 6. FOUR CORNER TURRETS SUPERSTRUCTURE (y = seatY to seatY + 32)
  const turretCenters = [
    { cx: 7, cz: 7, type: "spire" },
    { cx: 24, cz: 7, type: "flag_ne" },
    { cx: 7, cz: 24, type: "flag_sw" },
    { cx: 24, cz: 24, type: "spire" }
  ];

  for (const { cx, cz } of turretCenters) {
    for (let y = seatY + 1; y <= seatY + 30; y++) {
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          if (Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
          const isTurretWall = Math.abs(dx) === 2 || Math.abs(dz) === 2;
          const tx = cx + dx;
          const tz = cz + dz;
          if (isTurretWall) {
            setBlock(tx, y, tz, pickStone(tx, y, tz));
          }
        }
      }
    }
    // Turret floors at each story
    for (const fy of [seatY + 7, seatY + 16, seatY + 25]) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dz = -1; dz <= 1; dz++) {
          setBlock(cx + dx, fy, cz + dz, woodPlanks);
        }
      }
    }
    // Turret arrow loops at multiple levels
    setBlock(cx, seatY + 4, cz - 2, stoneWall);
    setBlock(cx, seatY + 11, cz - 2, stoneWall);
    setBlock(cx, seatY + 20, cz - 2, stoneWall);
  }

  // Spiral staircase in NW turret (cx=7, cz=7)
  const stairSteps = [
    { dx: -1, dz: 0, facing: "south" },
    { dx: 0, dz: -1, facing: "east" },
    { dx: 1, dz: 0, facing: "north" },
    { dx: 0, dz: 1, facing: "west" }
  ];
  for (let y = seatY + 1; y <= seatY + 25; y++) {
    setBlock(7, y, 7, stonePrimary); // Center pillar
    const step = stairSteps[(y - seatY - 1) % 4];
    setBlock(7 + step.dx, y, 7 + step.dz, getStairs(stoneStairs, step.facing));
  }
  // Doorways opening from stairwell into each floor
  for (const dy of [seatY + 1, seatY + 8, seatY + 17, seatY + 25]) {
    setBlock(7, dy, 9, "minecraft:air");
    setBlock(7, dy + 1, 9, "minecraft:air");
  }

  // 7. MACHICOLATIONS & BATTLEMENTS PARAPET (y = seatY + 24 to seatY + 27)
  const yCorbel = seatY + 24;
  // Corbel course projecting out 1 block on all 4 faces
  for (let x = 8; x <= 23; x++) {
    setBlock(x, yCorbel, 7, getStairs(stoneStairs, "north", "top"));
    setBlock(x, yCorbel, 24, getStairs(stoneStairs, "south", "top"));
  }
  for (let z = 8; z <= 23; z++) {
    setBlock(7, yCorbel, z, getStairs(stoneStairs, "west", "top"));
    setBlock(24, yCorbel, z, getStairs(stoneStairs, "east", "top"));
  }

  // Parapet walk floor (y = seatY + 25)
  for (let x = 7; x <= 24; x++) {
    for (let z = 7; z <= 24; z++) {
      const isWalk = x <= 11 || x >= 20 || z <= 11 || z >= 20;
      if (isWalk) {
        setBlock(x, seatY + 25, z, stonePrimary);
        // Machicolation trapdoor gaps
        if ((x % 3 === 0 || z % 3 === 0) && (x === 7 || x === 24 || z === 7 || z === 24)) {
          setBlock(x, seatY + 25, z, getTrapdoor(woodTrapdoor, "north", "top"));
        }
      }
    }
  }

  // Crenellated battlements (y = seatY + 26 to seatY + 27)
  for (let x = 8; x <= 23; x++) {
    // North wall
    if (x % 2 === 0) {
      setBlock(x, seatY + 26, 7, stonePrimary);
      setBlock(x, seatY + 27, 7, getSlab(stoneSlab, "bottom"));
    } else {
      setBlock(x, seatY + 26, 7, stoneWall);
    }
    // South wall
    if (x % 2 === 0) {
      setBlock(x, seatY + 26, 24, stonePrimary);
      setBlock(x, seatY + 27, 24, getSlab(stoneSlab, "bottom"));
    } else {
      setBlock(x, seatY + 26, 24, stoneWall);
    }
  }
  for (let z = 8; z <= 23; z++) {
    // West wall
    if (z % 2 === 0) {
      setBlock(7, seatY + 26, z, stonePrimary);
      setBlock(7, seatY + 27, z, getSlab(stoneSlab, "bottom"));
    } else {
      setBlock(7, seatY + 26, z, stoneWall);
    }
    // East wall
    if (z % 2 === 0) {
      setBlock(24, seatY + 26, z, stonePrimary);
      setBlock(24, seatY + 27, z, getSlab(stoneSlab, "bottom"));
    } else {
      setBlock(24, seatY + 26, z, stoneWall);
    }
  }

  // 8. CORNER TURRETS ROOF STRUCTURES & BANNERS (y = seatY + 30 to seatY + 38)
  for (const { cx, cz, type } of turretCenters) {
    // Turret corbel machicolations at y = seatY + 30
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        if (Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
        if (Math.abs(dx) === 2 || Math.abs(dz) === 2) {
          const facing = Math.abs(dx) >= Math.abs(dz) ? (dx > 0 ? "east" : "west") : (dz > 0 ? "south" : "north");
          setBlock(cx + dx, seatY + 30, cz + dz, getStairs(stoneStairs, facing, "top"));
        }
      }
    }
    // Turret parapet battlements
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        if (Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
        if (Math.abs(dx) === 2 || Math.abs(dz) === 2) {
          const isMerlon = (dx + dz) % 2 === 0;
          setBlock(cx + dx, seatY + 31, cz + dz, isMerlon ? stonePrimary : stoneWall);
        }
      }
    }

    if (type === "spire") {
      // Conical slate roof on NW and SE turrets
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          const dsq = dx * dx + dz * dz;
          if (dsq <= 8 && dsq >= 4) {
            const facing = Math.abs(dx) >= Math.abs(dz) ? (dx > 0 ? "east" : "west") : (dz > 0 ? "south" : "north");
            setBlock(cx + dx, seatY + 32, cz + dz, getStairs(roofStairs, facing));
          } else if (dsq < 4) {
            setBlock(cx + dx, seatY + 32, cz + dz, roofSolid);
          }
        }
      }
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          const dsq = dx * dx + dz * dz;
          if (dsq <= 5 && dsq >= 2) {
            const facing = Math.abs(dx) >= Math.abs(dz) ? (dx > 0 ? "east" : "west") : (dz > 0 ? "south" : "north");
            setBlock(cx + dx, seatY + 33, cz + dz, getStairs(roofStairs, facing));
          } else if (dsq < 2) {
            setBlock(cx + dx, seatY + 33, cz + dz, roofSolid);
          }
        }
      }
      // Upper spire cone
      setBlock(cx, seatY + 34, cz, roofSolid);
      setBlock(cx + 1, seatY + 34, cz, getStairs(roofStairs, "east"));
      setBlock(cx - 1, seatY + 34, cz, getStairs(roofStairs, "west"));
      setBlock(cx, seatY + 34, cz + 1, getStairs(roofStairs, "south"));
      setBlock(cx, seatY + 34, cz - 1, getStairs(roofStairs, "north"));

      setBlock(cx, seatY + 35, cz, roofSolid);
      setBlock(cx, seatY + 36, cz, roofSolid);
      setBlock(cx, seatY + 37, cz, stoneWall);
    } else if (type === "flag_ne") {
      // NE Turret Flagpole & Royal Blue/Gold Pennant
      for (let y = seatY + 31; y <= seatY + 37; y++) {
        setBlock(cx, y, cz, woodFence);
      }
      setBlock(cx + 1, seatY + 37, cz, "minecraft:blue_wool");
      setBlock(cx + 2, seatY + 37, cz, "minecraft:yellow_wool");
      setBlock(cx + 3, seatY + 37, cz, "minecraft:blue_wool");

      setBlock(cx + 1, seatY + 36, cz, "minecraft:yellow_wool");
      setBlock(cx + 2, seatY + 36, cz, "minecraft:blue_wool");
      setBlock(cx + 3, seatY + 36, cz, "minecraft:yellow_wool");

      setBlock(cx + 1, seatY + 35, cz, "minecraft:blue_wool");
      setBlock(cx + 2, seatY + 35, cz, "minecraft:yellow_wool");

      setBlock(cx + 1, seatY + 34, cz, "minecraft:yellow_wool");
    } else if (type === "flag_sw") {
      // SW Turret Flagpole & Red/Gold Pennant
      for (let y = seatY + 31; y <= seatY + 37; y++) {
        setBlock(cx, y, cz, woodFence);
      }
      setBlock(cx + 1, seatY + 37, cz, "minecraft:red_wool");
      setBlock(cx + 2, seatY + 37, cz, "minecraft:yellow_wool");
      setBlock(cx + 3, seatY + 37, cz, "minecraft:red_wool");

      setBlock(cx + 1, seatY + 36, cz, "minecraft:yellow_wool");
      setBlock(cx + 2, seatY + 36, cz, "minecraft:red_wool");
      setBlock(cx + 3, seatY + 36, cz, "minecraft:yellow_wool");

      setBlock(cx + 1, seatY + 35, cz, "minecraft:red_wool");
      setBlock(cx + 2, seatY + 35, cz, "minecraft:yellow_wool");

      setBlock(cx + 1, seatY + 34, cz, "minecraft:red_wool");
    }
  }

  // 9. CENTRAL HIGH KEEP TOWER & BELFRY (y = seatY + 25 to seatY + 36)
  // Central tower walls
  for (let y = seatY + 25; y <= seatY + 31; y++) {
    for (let x = 12; x <= 19; x++) {
      for (let z = 12; z <= 19; z++) {
        const isWall = x === 12 || x === 19 || z === 12 || z === 19;
        if (isWall) {
          setBlock(x, y, z, pickStone(x, y, z));
        }
      }
    }
  }

  // Arched lookout belfry openings at y = seatY + 28 to seatY + 30
  const belfryOpenings = [
    { x: [15, 16], z: 12, facing1: "west", facing2: "east" },
    { x: [15, 16], z: 19, facing1: "west", facing2: "east" },
    { x: 12, z: [15, 16], facing1: "north", facing2: "south" },
    { x: 19, z: [15, 16], facing1: "north", facing2: "south" }
  ];
  for (const b of belfryOpenings) {
    if (Array.isArray(b.x)) {
      setBlock(b.x[0], seatY + 28, b.z, woodFence);
      setBlock(b.x[1], seatY + 28, b.z, woodFence);
      setBlock(b.x[0], seatY + 29, b.z, "minecraft:air");
      setBlock(b.x[1], seatY + 29, b.z, "minecraft:air");
      setBlock(b.x[0], seatY + 30, b.z, getStairs(stoneStairs, b.facing1, "top"));
      setBlock(b.x[1], seatY + 30, b.z, getStairs(stoneStairs, b.facing2, "top"));
    } else {
      setBlock(b.x, seatY + 28, b.z[0], woodFence);
      setBlock(b.x, seatY + 28, b.z[1], woodFence);
      setBlock(b.x, seatY + 29, b.z[0], "minecraft:air");
      setBlock(b.x, seatY + 29, b.z[1], "minecraft:air");
      setBlock(b.x, seatY + 30, b.z[0], getStairs(stoneStairs, b.facing1, "top"));
      setBlock(b.x, seatY + 30, b.z[1], getStairs(stoneStairs, b.facing2, "top"));
    }
  }

  // Central Tower Peaked Roof
  // Eaves course at y = seatY + 32
  for (let x = 11; x <= 20; x++) {
    setBlock(x, seatY + 32, 11, getStairs(roofStairs, "north"));
    setBlock(x, seatY + 32, 20, getStairs(roofStairs, "south"));
  }
  for (let z = 11; z <= 20; z++) {
    setBlock(11, seatY + 32, z, getStairs(roofStairs, "west"));
    setBlock(20, seatY + 32, z, getStairs(roofStairs, "east"));
  }

  // Roof Tier 1 at y = seatY + 33
  for (let x = 12; x <= 19; x++) {
    setBlock(x, seatY + 33, 12, getStairs(roofStairs, "south"));
    setBlock(x, seatY + 33, 19, getStairs(roofStairs, "north"));
  }
  for (let z = 12; z <= 19; z++) {
    setBlock(12, seatY + 33, z, getStairs(roofStairs, "east"));
    setBlock(19, seatY + 33, z, getStairs(roofStairs, "west"));
  }

  // Roof Tier 2 at y = seatY + 34
  for (let x = 13; x <= 18; x++) {
    setBlock(x, seatY + 34, 13, getStairs(roofStairs, "south"));
    setBlock(x, seatY + 34, 18, getStairs(roofStairs, "north"));
  }
  for (let z = 13; z <= 18; z++) {
    setBlock(13, seatY + 34, z, getStairs(roofStairs, "east"));
    setBlock(18, seatY + 34, z, getStairs(roofStairs, "west"));
  }

  // Roof Tier 3 at y = seatY + 35
  for (let x = 14; x <= 17; x++) {
    setBlock(x, seatY + 35, 14, getStairs(roofStairs, "south"));
    setBlock(x, seatY + 35, 17, getStairs(roofStairs, "north"));
  }
  for (let z = 14; z <= 17; z++) {
    setBlock(14, seatY + 35, z, getStairs(roofStairs, "east"));
    setBlock(17, seatY + 35, z, getStairs(roofStairs, "west"));
  }

  // Roof Ridge & Cap at y = seatY + 36
  for (let x = 15; x <= 16; x++) {
    for (let z = 15; z <= 16; z++) {
      setBlock(x, seatY + 36, z, roofSolid);
    }
  }

  // 10. GRAND CITADEL ROYAL WAR STANDARD (y = seatY + 36 to seatY + 41)
  for (let y = seatY + 36; y <= seatY + 41; y++) {
    setBlock(16, y, 15, woodFence);
  }
  // Fluttering swallow-tail royal banner overlooking the city roofs
  setBlock(17, seatY + 41, 15, "minecraft:red_wool");
  setBlock(18, seatY + 41, 15, "minecraft:yellow_wool");
  setBlock(19, seatY + 41, 15, "minecraft:red_wool");

  setBlock(17, seatY + 40, 15, "minecraft:yellow_wool");
  setBlock(18, seatY + 40, 15, "minecraft:red_wool");
  setBlock(19, seatY + 40, 15, "minecraft:yellow_wool");
  setBlock(20, seatY + 40, 15, "minecraft:red_wool");

  setBlock(17, seatY + 39, 15, "minecraft:red_wool");
  setBlock(18, seatY + 39, 15, "minecraft:yellow_wool");
  setBlock(19, seatY + 39, 15, "minecraft:red_wool");

  setBlock(17, seatY + 38, 15, "minecraft:yellow_wool");
  setBlock(18, seatY + 38, 15, "minecraft:red_wool");

  return {
    name: "hilltop_castle_keep",
    seatY: seatY,
    anchors: {
      front: [16, seatY + 1, 0],
      door: [16, seatY + 1, 7],
      keep_summit: [16, seatY + 41, 15]
    },
    interiors: [
      {
        min: [10, seatY + 1, 10],
        max: [21, seatY + 6, 21],
        kind: "vault"
      },
      {
        min: [10, seatY + 8, 10],
        max: [21, seatY + 15, 21],
        kind: "hall"
      },
      {
        min: [10, seatY + 17, 10],
        max: [21, seatY + 23, 21],
        kind: "quarters"
      },
      {
        min: [13, seatY + 26, 13],
        max: [18, seatY + 31, 18],
        kind: "quarters"
      }
    ]
  };
}
